def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    opp_d = 0
    for a, b in history:
        if b == 'D':
            opp_d += 1
    if opp_d > 0:
        last_my, last_opp = history[-1]
        if last_opp == 'C':
            return 'C'
        else:
            if n >= 2 and history[-2][0] == 'D' and opp_d * 2 < n:
                return 'C'
            return 'D'
    else:
        if n % 10 == 9:
            return 'D'
        return 'C'
